{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.budget import remaining"
  ],
  "tests": [
    {
      "name": "test_remaining_overspend_is_negative",
      "intent": "overspending returns a negative amount instead of zero",
      "code": "# intent: overspending returns a negative amount instead of zero\ndef test_remaining_overspend_is_negative():\n    assert remaining(Decimal(\"100.00\"), [Decimal(\"60.00\"), Decimal(\"55.00\")]) == Decimal(\"-15.00\")\n"
    },
    {
      "name": "test_remaining_exact_spend_is_zero",
      "intent": "spending exactly the budget leaves zero",
      "code": "# intent: spending exactly the budget leaves zero\ndef test_remaining_exact_spend_is_zero():\n    assert remaining(Decimal(\"100.00\"), [Decimal(\"100.00\")]) == Decimal(\"0.00\")\n"
    },
    {
      "name": "test_remaining_empty_spent_returns_budget",
      "intent": "no spending returns the full budget",
      "code": "# intent: no spending returns the full budget\ndef test_remaining_empty_spent_returns_budget():\n    assert remaining(Decimal(\"100.00\"), []) == Decimal(\"100.00\")\n"
    },
    {
      "name": "test_remaining_negative_spending_raises",
      "intent": "negative spending is rejected with ValueError",
      "code": "# intent: negative spending is rejected with ValueError\ndef test_remaining_negative_spending_raises():\n    with pytest.raises(ValueError):\n        remaining(Decimal(\"100.00\"), [Decimal(\"-5.00\")])\n"
    },
    {
      "name": "test_remaining_zero_budget_with_spending",
      "intent": "zero budget with spending yields negative remaining",
      "code": "# intent: zero budget with spending yields negative remaining\ndef test_remaining_zero_budget_with_spending():\n    assert remaining(Decimal(\"0.00\"), [Decimal(\"10.00\")]) == Decimal(\"-10.00\")\n"
    },
    {
      "name": "test_remaining_multiple_spent_including_zero",
      "intent": "zero amounts in spent do not affect the result",
      "code": "# intent: zero amounts in spent do not affect the result\ndef test_remaining_multiple_spent_including_zero():\n    assert remaining(Decimal(\"50.00\"), [Decimal(\"20.00\"), Decimal(\"0.00\"), Decimal(\"5.00\")]) == Decimal(\"25.00\")\n"
    }
  ]
}
